    CorporateWorker(int id, std::string n, double s, std::string d) : employee_id(id), name(n), salary(s), department(d) {}

    // Method to adjust salary
    void adjust_salary(double increment) {
        salary += increment;
    }

    // Method to find average salary in a given department
    static double average_salary_in_department(const std::vector<CorporateWorker>& workers, const std::string& dept) {
        double total_salary = 0.0;
        int count = 0;
        for (const auto& worker : workers) {
            if (worker.department == dept) {
                total_salary += worker.salary;
                count++;
            }
        }
        return count == 0 ? 0.0 : total_salary / count;
    }

    // Method to find the highest earning employee in the department
    static CorporateWorker highest_earning_employee(const std::vector<CorporateWorker>& workers, const std::string& dept) {
        CorporateWorker highest;
        double max_salary = 0.0;
        for (const auto& worker : workers) {
            if (worker.department == dept && worker.salary > max_salary) {
                max_salary = worker.salary;
                highest = worker;
            }
        }
        return highest;
    }

    // Method to display all employees in the department
    static void display_employees_in_department(const std::vector<CorporateWorker>& workers, const std::string& dept) {
