    // Definition for singly-linked list.
    public static class ListNode {
        int val;
        ListNode next;
        ListNode(int x) { val = x; }
    }

    /**
     * Merges two sorted linked lists in ascending order without duplicates.
     * @param list1 The first linked list.
     * @param list2 The second linked list.
     * @return The merged linked list.
     */
    public static ListNode mergeLists(ListNode list1, ListNode list2) {
        // Input validation: Check if either list is null
        if (list1 == null) {
            return list2;
        }
        if (list2 == null) {
            return list1;
        }

        // Initialize pointers for both lists
        ListNode p1 = list1;
        ListNode p2 = list2;

        // Determine the head of the merged list
        if (p1.val < p2.val) {
            ListNode head = p1;
            p1 = p1.next;
        } else {
            ListNode head = p2;
            p2 = p2.next;
        }

        ListNode current = head;

        // Merge the two lists
        while (p1 != null && p2 != null) {
            if (p1.val < p2.val) {
                // Check for duplicates
                if (current.next != null && current.next.val == p1.val) {
                    // Skip duplicate
                    p1 = p1.next;
                    continue;
                }
                current.next = p1;
                current = p1;
                p1 = p1.next;
            } else if (p1.val > p2.val) {
                // Check for duplicates
                if (current.next != null && current.next.val == p2.val) {
                    // Skip duplicate
                    p2 = p2.next;
                    continue;
                }
                current.next = p2;
                current = p2;
                p2 = p2.next;
            } else {
                // Values are equal, check for duplicates
                if (current.next != null && current.next.val == p1.val) {
                    // Skip duplicate
                    p1 = p1.next;
                    p2 = p2.next;
                    continue;
                }
                // Add the node with the same value
                current.next = p1;
                current = p1;
                p1 = p1.next;
                p2 = p2.next;
            }
        }

        // Attach the remaining elements of the non-exhausted list
        while (p1 != null) {
            if (current.next != null && current.next.val == p1.val) {
