    pub fn transform_data(raw_data: &[u8]) -> Result<HashMap<String, Value>, Box<dyn std::error::Error + Send + Sync>> {
        let json: Value = serde_json::from_slice(raw_data)?;
        let mut transformed_data = HashMap::new();

