        if let Some(sensor_data) = json.get("sensor_data") {
            if let Some(readings) = sensor_data.as_array() {
                for reading in readings {
                    if let Some(id) = reading.get("id") {
                        if let Some(value) = reading.get("value") {
                            transformed_data.insert(id.as_str().unwrap().to_string(), value.clone());
                        }
                    }
                }
            }
        }

        Ok(transformed_data)
    }
}
