// graph_db.rs
use neo4j::Session;
use neo4j::types::Value;
use std::collections::HashMap;

pub struct GraphDatabase {
    session: Session,
}

impl GraphDatabase {
    pub fn new(uri: &str, user: &str, password: &str) -> Self {
        let session = Session::builder(uri, user, password)
            .expect("Failed to create Neo4j session");
        GraphDatabase { session }
    }

    pub fn store_data(&self, data: &HashMap<String, Value>) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        for (id, value) in data {
            let query = format!("CREATE (n:Sensor {{id: '{}', value: $value}})", id);
            self.session
                .run(&query, &[("value", value)])
                .map_err(|e| format!("Failed to store data in Neo4j: {}", e))?;
        }
        Ok(())
    }
}
